// /status, /retry, /new and rules commands, well-formed A1 / storyboard / A2 / intake buttons, and replies with notes to a storyboard request reach the
// database; anything else is ignored. Storyboard requests (WF-12) end with "ref:<token>".
const update = $input.first().json;
// /status [video id prefix] (P-017) is answered from telegram_status(); approvers only.
const statusCommand = /^\/status(?:@\w+)?(?:\s+([0-9a-fA-F-]{1,36}))?\s*$/.exec(update.message?.text ?? '');
if (update.message && statusCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'status',
      prefix: (statusCommand[1] ?? '').toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// /retry <video id prefix> (D-056) gives a permanently failed job one more attempt; approvers only.
const retryCommand = /^\/retry(?:@\w+)?\s+([0-9a-fA-F-]{4,36})\s*$/.exec(update.message?.text ?? '');
if (update.message && retryCommand && !update.message.from?.is_bot) {
  return [{
    json: {
      kind: 'retry',
      prefix: retryCommand[1].toLowerCase(),
      userId: String(update.message.from.id),
      chatId: String(update.message.chat.id),
      messageId: String(update.message.message_id),
    },
  }];
}
// Channel rules (D-059): /rules [video|tts|say], /rules file <scope>, a .md/.txt file captioned
// /rules set <scope>, /rule add <video|tts> <text>, /rule del <number>, /say <term> = <spoken>,
// /unsay <term>. telegram_rules() checks the user.
const rulesText = update.message?.text ?? update.message?.caption ?? '';
const rulesCommand = /^\/(rules|rule|say|unsay)(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(rulesText);
if (update.message && rulesCommand && !update.message.from?.is_bot) {
  const message = update.message;
  const base = {
    kind: 'rules',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
    scope: '',
    text: '',
    extra: '',
    fileId: '',
    exportFile: false,
    error: '',
  };
  const scopes = { video: 'video', tts: 'tts', say: 'pronunciation' };
  const usage = 'Usage: /rules [video|tts|say] · /rules file <video|tts|say> · /rule add <video|tts> <text> · /rule del <number> · /say <term> = <how to say it> · /unsay <term> · send a .md/.txt file with the caption /rules set <video|tts|say>';
  const out = (fields) => [{ json: { ...base, ...fields } }];
  const [, command, restRaw] = rulesCommand;
  const rest = restRaw.trim();
  if (command === 'rules') {
    const parts = rest.split(/\s+/).filter(Boolean);
    if (parts.length === 0) return out({ action: 'VIEW' });
    if (parts.length === 1 && scopes[parts[0]]) return out({ action: 'VIEW', scope: scopes[parts[0]] });
    if (parts.length === 2 && parts[0] === 'file' && scopes[parts[1]]) {
      return out({ action: 'VIEW', scope: scopes[parts[1]], exportFile: true });
    }
    if (parts.length === 2 && parts[0] === 'set' && scopes[parts[1]]) {
      const file = message.document;
      if (!file) return out({ error: 'Attach the edited .md or .txt file with the caption /rules set <video|tts|say>.' });
      if (!/\.(md|txt)$/i.test(file.file_name ?? '') || (file.file_size ?? 0) > 200000) {
        return out({ error: 'The rules must be a .md or .txt file of at most 200 KB.' });
      }
      return out({ action: 'SET', scope: scopes[parts[1]], fileId: file.file_id });
    }
    return out({ error: usage });
  }
  if (command === 'rule') {
    const add = /^add\s+(video|tts)\s+([\s\S]+)$/.exec(rest);
    if (add) return out({ action: 'ADD', scope: add[1], text: add[2].trim() });
    const del = /^del\s+#?(\d{1,18})$/.exec(rest);
    if (del) return out({ action: 'DELETE', text: del[1] });
    return out({ error: usage });
  }
  if (command === 'say') {
    const say = /^([^=\n]+?)\s*=\s*(.+)$/.exec(rest);
    if (say) return out({ action: 'SAY', scope: 'pronunciation', text: say[1].trim(), extra: say[2].trim() });
    return out({ error: usage });
  }
  if (rest === '' || rest.includes('\n')) return out({ error: usage });
  return out({ action: 'UNSAY', scope: 'pronunciation', text: rest });
}
// /new [minutes] <topic> (D-058), notes on the next lines, optionally as the caption of a .md/.txt
// file holding the full brief. Only in the approval chat; telegram_intake_draft() checks the user.
const APPROVAL_CHAT = 'REPLACE_WITH_APPROVAL_CHAT_ID';
const newCommand = /^\/new(?:@\w+)?(?=\s|$)([\s\S]*)$/.exec(update.message?.text ?? update.message?.caption ?? '');
if (update.message && newCommand && !update.message.from?.is_bot) {
  const message = update.message;
  const base = {
    kind: 'intake',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
  };
  const fail = (error) => [{ json: { ...base, error } }];
  if (String(message.chat.id) !== APPROVAL_CHAT) {
    return fail(`This chat (${message.chat.id}) is not the approval chat; /new works only there.`);
  }
  const [first = '', ...rest] = newCommand[1].trim().split('\n');
  const minutes = /^(\d{1,2})\s+(\S[\s\S]*)$/.exec(first.trim());
  const topic = (minutes ? minutes[2] : first).trim();
  if (topic === '') {
    return fail('Usage: /new [minutes] <topic>, notes on the next lines; attach the full brief as a .md or .txt file with this as its caption.');
  }
  const file = message.document;
  if (file && (!/\.(md|txt)$/i.test(file.file_name ?? '') || (file.file_size ?? 0) > 200000)) {
    return fail('The full brief must be a .md or .txt file of at most 200 KB.');
  }
  return [{
    json: {
      ...base,
      topic,
      minutes: minutes ? Number(minutes[1]) : null,
      notes: rest.join('\n').trim(),
      fileId: file?.file_id ?? '',
      error: '',
    },
  }];
}
const query = update.callback_query;
const actions = { A: 'APPROVE', G: 'REGENERATE', R: 'REJECT' };
if (query) {
  const match = /^(a1|sb|a2|in):([AGR]):([0-9a-f]{32})$/.exec(query.data ?? '');
  if (!match || (match[1] !== 'a1' && match[2] === 'G')) return [];
  return [{
    json: {
      kind: 'button',
      approval: { a1: 'script', sb: 'storyboard', a2: 'preview', in: 'intake' }[match[1]],
      queryId: query.id,
      userId: String(query.from.id),
      chatId: String(query.message?.chat?.id ?? ''),
      messageId: String(query.message?.message_id ?? ''),
      originalText: String(query.message?.text ?? ''),
      action: actions[match[2]],
      token: match[3],
      note: '',
    },
  }];
}
const message = update.message;
const repliedTo = message?.reply_to_message;
const ref = /ref:([0-9a-f]{32})/.exec(repliedTo?.text ?? '');
if (!message || message.from?.is_bot || !repliedTo?.from?.is_bot || !ref || typeof message.text !== 'string') return [];
return [{
  json: {
    kind: 'reply',
    approval: 'storyboard',
    userId: String(message.from.id),
    chatId: String(message.chat.id),
    messageId: String(message.message_id),
    action: 'FEEDBACK',
    token: ref[1],
    note: message.text.trim(),
  },
}];

// telegram_decide() result codes -> short replies. Buttons are removed once the request is
// settled (decided, superseded, expired); a refused stranger leaves the message untouched. Replies
// with notes (storyboard or A2) are answered in the chat; both revise the storyboard.
const input = $('Parse callback').first().json;
const { result, version, round, video_id: videoId } = $input.first().json;
const storyboard = input.approval === 'storyboard';
const preview = input.approval === 'preview';
const intake = input.approval === 'intake';
const notes = `Notes received: revising the storyboard (round ${round} of 4).`;
const done = intake
  ? {
      APPROVE: `Created video ${String(videoId).slice(0, 8)}: writing the script; the A1 request follows.`,
      REJECT: 'Cancelled; nothing was created.',
    }
  : storyboard
  ? { APPROVE: 'Approved: rendering the preview', REJECT: 'Rejected (video cancelled)', FEEDBACK: notes }
  : preview
    ? { APPROVE: 'Approved: rendering the final 1080p', REJECT: 'Rejected (video cancelled)' }
    : { APPROVE: 'Approved', REJECT: 'Rejected (video cancelled)', REGENERATE: `Regenerating as v${version}` };
const replies = {
  OK: done[input.action],
  NOT_ALLOWED: 'You are not an approver.',
  NOT_FOUND: 'Unknown approval.',
  NOT_PENDING: 'Already decided.',
  EXPIRED: 'This request expired.',
  SUPERSEDED: 'A newer version exists; this request is no longer valid.',
  HASH_MISMATCH: `The ${storyboard ? 'storyboard' : preview ? 'preview' : 'script'} changed after this request; wait for the new request.`,
  EMPTY_NOTE: 'Write your notes in the reply text.',
  NOT_SUPPORTED: 'Not available for this request.',
  NEEDS_DECISION: 'That was the last round of notes; the video needs a decision.',
};
const settled = ['OK', 'NOT_PENDING', 'EXPIRED', 'SUPERSEDED', 'NEEDS_DECISION'].includes(result);
const decidedAt = new Date().toISOString().replace('T', ' ').slice(0, 16);
const answer = replies[result] ?? `Not applied (${result}).`;
return [{
  json: {
    answer,
    settled,
    isButton: input.kind !== 'reply',
    chatId: input.chatId,
    messageId: input.messageId,
    queryId: input.queryId,
    editedText: `${input.originalText}\n\n${result === 'OK' ? 'Decision' : 'Closed'}: ${answer} (${decidedAt} UTC)`.slice(0, 4096),
  },
}];

// telegram_status() rows -> one status message (P-017). System text is English; titles are
// quoted Vietnamese video content. Times are minutes since the step or job started.
const input = $('Parse callback').first().json;
const rows = $input.all().map((item) => item.json).filter((row) => row.allowed !== undefined);
const reply = (text) => [{ json: { text: text.slice(0, 4096), chatId: input.chatId, messageId: input.messageId } }];
if (rows.some((row) => row.allowed === false)) return reply('You are not an approver.');
if (rows.length === 0) {
  return reply(input.prefix ? `[AI Video] No video id starts with ${input.prefix}.` : '[AI Video] No active videos.');
}
const minutes = (from, to = Date.now()) => {
  const m = Math.max(0, Math.round((new Date(to).getTime() - new Date(from).getTime()) / 60_000));
  return m < 60 ? `${m} min` : `${Math.floor(m / 60)} h ${String(m % 60).padStart(2, '0')} min`;
};
const describe = (p) => {
  if (!p || !p.stage) return '';
  const turn = p.turn ? ` ${p.turn}/${p.of}` : '';
  switch (p.stage) {
    case 'agent': return `agent turn${turn}`;
    case 'gates': return `checking (turn${turn})`;
    case 'tts': return `narration ${p.scene}/${p.of}`;
    case 'voice': return 'joining the voice';
    case 'whisper': return 'whisper';
    case 'render': return `rendering ${p.frames ?? ''} frames`.replace('  ', ' ');
    case 'loudness': return 'loudness';
    default: return String(p.stage);
  }
};
const head = (row) => `${String(row.video_id).slice(0, 8)} v${row.version} · ${row.title ?? '?'}`;
const cost = (row) => Object.entries(row.cost ?? {}).map(([c, v]) => `${Math.round(v * 100) / 100} ${c}`).join(', ');

if (input.prefix) {
  const row = rows[0];
  const marks = { SUCCEEDED: '✓', RUNNING: '▶', FAILED_PERMANENT: '✗', FAILED_RETRYABLE: '↻', BLOCKED: '⏸' };
  const jobs = (row.jobs ?? []).map((job) => {
    const parts = [`${marks[job.status] ?? '·'} ${job.step}`];
    if (job.started) parts.push(minutes(job.started, job.status === 'RUNNING' ? undefined : job.finished ?? undefined));
    else parts.push('waiting');
    if (job.attempts > 1) parts.push(`${job.attempts} attempts`);
    if (job.status === 'RUNNING' && describe(job.progress)) parts.push(describe(job.progress));
    if (job.error && job.status !== 'SUCCEEDED') parts.push(job.error);
    return parts.join(' · ');
  });
  return reply([
    `[AI Video] Video ${head(row)}`,
    `Status: ${row.status} (${minutes(row.status_since)})`,
    ...jobs,
    cost(row) ? `Cost: ${cost(row)}` : 'Cost: none recorded',
    ...(row.approval ? [`Waiting for: ${row.approval}`] : []),
    ...(row.status === 'NEEDS_DECISION' ? [`Retry the failed step: /retry ${String(row.video_id).slice(0, 8)}`] : []),
  ].join('\n'));
}

const lines = rows.flatMap((row) => {
  const step = row.step
    ? `${row.step} ${String(row.step_status).toLowerCase()} ${minutes(row.step_since)}`
    : 'no job yet';
  const extra = [describe(row.progress), `${row.steps_done}/${row.steps_total} jobs done`, row.approval ? `waiting for ${row.approval}` : '']
    .filter(Boolean);
  return ['', head(row), [row.status, step, ...extra].join(' · ')];
});
return reply([`[AI Video] ${rows.length} active video${rows.length === 1 ? '' : 's'}`, ...lines, '', 'Details: /status <first 8 characters of the id>'].join('\n'));

// telegram_retry() result -> one reply (D-056). System text is English.
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const id = row.video_id ? String(row.video_id).slice(0, 8) : input.prefix;
const texts = {
  RETRIED: `[AI Video] Retrying ${row.step} of video ${id} (attempt ${row.attempt}). Progress: /status ${id}`,
  NOT_APPROVER: 'You are not an approver.',
  NOT_FOUND: `[AI Video] No video id starts with ${input.prefix}.`,
  AMBIGUOUS: `[AI Video] Several video ids start with ${input.prefix}; send more characters.`,
  NOT_STOPPED: `[AI Video] Video ${id} is not waiting for a decision; nothing to retry.`,
  NO_FAILED_JOB: `[AI Video] Video ${id} has no failed job to retry.`,
};
const text = texts[row.result] ?? `[AI Video] Retry failed: ${row.result ?? 'no answer'}.`;
return [{ json: { text, chatId: input.chatId, messageId: input.messageId } }];

// /new -> the brief for telegram_intake_draft() (D-058); a parse error becomes the reply instead.
// The full brief file is read as UTF-8 text and kept verbatim (only a byte order mark is dropped).
const input = $('Parse callback').first().json;
const reply = { chatId: input.chatId, messageId: input.messageId };
if (input.error) return [{ json: { ...reply, ok: false, text: input.error } }];
const fullBrief = input.fileId
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '')
  : '';
const brief = {
  topic: input.topic,
  ...(input.minutes ? { duration_minutes: input.minutes } : {}),
  ...(fullBrief.trim() ? { full_brief: fullBrief } : {}),
  ...(input.notes ? { notes: input.notes } : {}),
};
return [{ json: { ...reply, ok: true, userId: input.userId, brief: JSON.stringify(brief) } }];

// telegram_intake_draft() -> the confirmation with Create / Cancel (callback in:<A|R>:<token>), or
// the reason nothing was drafted. System text is English; the topic and notes are quoted video
// content.
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
if (row.result === 'NOT_APPROVER') return [{ json: { ...reply, text: 'You are not an approver.' } }];
if (row.result !== 'DRAFT') {
  return [{ json: { ...reply, text: `[AI Video] Not created: ${row.error ?? row.result ?? 'no answer'}` } }];
}
const brief = typeof row.brief === 'string' ? JSON.parse(row.brief) : row.brief;
const text = [
  '[AI Video] New episode: confirm',
  `Topic: ${brief.topic}`,
  `Length: ${brief.duration_minutes ? `about ${brief.duration_minutes} min` : 'not set (about 6 min)'}`,
  `Full brief: ${brief.full_brief ? `${brief.full_brief.length} characters` : 'none (Claude writes the episode)'}`,
  ...(brief.notes ? [`Notes: ${brief.notes}`] : []),
  ...(row.has_voice === false
    ? ['', 'Warning: the full brief has no VOICE section. With a full brief the script copies every narration line verbatim from it, so this brief will fail. Add a VOICE section, or send the outline as notes instead.']
    : []),
  '',
  `Expires: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
].join('\n');
return [{ json: { ...reply, text, approve: `in:A:${row.token}`, reject: `in:R:${row.token}` } }];

// A rules command -> the arguments of telegram_rules() (D-059); a usage error becomes the reply.
// A /rules set file is read as UTF-8 (a byte order mark is dropped).
const input = $('Parse callback').first().json;
const reply = { chatId: input.chatId, messageId: input.messageId };
if (input.error) return [{ json: { ...reply, ok: false, text: input.error } }];
const text = input.fileId
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8').replace(/^\uFEFF/, '')
  : input.text;
return [{
  json: {
    ...reply,
    ok: true,
    userId: input.userId,
    action: input.action,
    scope: input.scope,
    text,
    extra: input.extra,
  },
}];

// telegram_rules() -> the reply (D-059): the rules list, a confirmation, a refusal, or a Markdown
// file to edit (/rules file). System text is English; rules are quoted as written.
const input = $('Parse callback').first().json;
const row = $input.first()?.json ?? {};
const reply = { chatId: input.chatId, messageId: input.messageId };
const say = (text) => [{ json: { ...reply, exportFile: false, text: text.slice(0, 4096) } }];
if (row.result === 'NOT_APPROVER') return say('You are not an approver.');
if (row.result === 'INVALID') return say(`[AI Video] Not changed: ${row.detail}`);
if (row.result === 'NOT_FOUND') {
  return say(input.action === 'DELETE' ? `[AI Video] No rule #${row.detail}.` : `[AI Video] No pronunciation for "${row.detail}".`);
}
if (row.result !== 'OK') return say(`[AI Video] Rules: ${row.result ?? 'no answer'}`);
const rules = typeof row.rules === 'string' ? JSON.parse(row.rules) : row.rules;
const names = { video: 'Video', tts: 'TTS', pronunciation: 'Pronunciation' };
const items = (scope) =>
  scope === 'pronunciation'
    ? rules.pronunciation.map((p) => `${p.term} = ${p.spoken}`)
    : rules[scope].map((r) => `#${r.id} ${r.text}`);
if (input.exportFile) {
  const scope = input.scope;
  const header = scope === 'pronunciation'
    ? ['# Pronunciation', '', 'One "term = how to say it" per list item (case-sensitive, whole words); other lines are ignored.']
    : [`# ${names[scope]} rules`, '', 'One rule per list item; other lines are ignored.'];
  const list = scope === 'pronunciation' ? items(scope) : rules[scope].map((r) => r.text);
  return [{
    json: {
      ...reply,
      exportFile: true,
      fileName: `${scope === 'pronunciation' ? 'say' : scope}-rules.md`,
      markdown: [...header, '', ...list.map((item) => `- ${item}`), ''].join('\n'),
      caption: `Edit and send back with the caption /rules set ${scope === 'pronunciation' ? 'say' : scope}`,
    },
  }];
}
const done = {
  ADD: () => `[AI Video] Added rule #${row.detail} (${names[input.scope]}).`,
  DELETE: () => `[AI Video] Removed rule #${input.text}.`,
  SET: () => `[AI Video] ${names[input.scope]} rules replaced: ${rules[input.scope].length} now.`,
  SAY: () => `[AI Video] "${input.text}" is now read as "${input.extra}".`,
  UNSAY: () => `[AI Video] "${input.text}" is read as written again.`,
}[input.action];
if (done) return say(`${done()} Applies to steps that start from now on.`);
const scopes = input.scope ? [input.scope] : ['video', 'tts', 'pronunciation'];
const lines = scopes.flatMap((scope) => ['', `${names[scope]}:`, ...(items(scope).length ? items(scope) : ['(none)'])]);
const text = [`[AI Video] Channel rules (version ${String(rules.version).slice(0, 8)})`, ...lines, '', 'Edit: /rule add video|tts <text> · /rule del <number> · /say <term> = <how to say it> · /unsay <term> · /rules file video|tts|say'].join('\n');
return say(text.length > 4096 ? `${text.slice(0, 3900)}\n…\nToo long for one message: use /rules file video|tts|say.` : text);

// The rules as a Markdown file for /rules file (D-059).
const row = $input.first().json;
const data = await this.helpers.prepareBinaryData(Buffer.from(row.markdown, 'utf8'), row.fileName, 'text/markdown');
return [{ json: { chatId: row.chatId, messageId: row.messageId, caption: row.caption }, binary: { data } }];
